return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Russian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-12 17:56+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ru_RU','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" сохранено.','"%1$s" created. %2$d template updated.'=>'"%1$s" создан. %2$d шаблонов обновлено.' . "\0" . '"%1$s" создан. %2$d шаблонов обновлено.' . "\0" . '','"%s" created.'=>'"%s" создан.','"product" (replaces "article")'=>'"продукт" (заменяет "статью")','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Обрабатывать H2 как эквивалент H1" (Настройки → SEO → Анализ): включите это, когда ваша тема отображает заголовок поста внутри H2 вместо H1. Анализатор поднимает первый H2 до H1, чтобы оценка не была неправильно понижена.','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d символов — хорошо, немного выше идеала %2$d, но в пределах допустимого диапазона %3$d символов. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d символов — идеальная длина. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d символов — вероятно, обрезано в результатах поиска (держите под %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d символов — слишком коротко (стремитесь к %2$d–%3$d). %4$s','%1$d chars, %2$d words — good title.'=>'%1$d символов, %2$d слов — хороший заголовок.','%1$d internal, %2$d external.'=>'%1$d внутренних, %2$d внешних.','%1$d of %2$d image(s) missing alt text.'=>'%1$d из %2$d изображений без альтернативного текста.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d опубликованных сообщений с тегом _lf_lang = %2$s.' . "\0" . '%1$d опубликованных сообщений с тегом _lf_lang = %2$s.' . "\0" . '','%1$d translated, %2$d skipped.'=>'%1$d переведено, %2$d пропущено.','%1$d words — below recommended minimum of %2$d.'=>'%1$d слов — ниже рекомендуемого минимума в %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d слов — очень тонкий контент. Рассмотрите возможность расширения как минимум до %2$d слов.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d уже переведено — <a href="#" class="lf-force-translate">принудительно повторный перевод</a>','%d external link(s), no internal links.'=>'%d внешняя(ие) ссылка(и), без внутренних ссылок.','%d external link(s), no internal links. Add internal links to related content.'=>'%d внешних ссылок, без внутренних. Добавьте внутренние ссылки на связанный контент.','%d H1 tags found — a page should have exactly one H1.'=>'Обнаружено %d тегов H1 — у страницы должно быть ровно один H1.','%d image(s), all have alt text.'=>'%d изображений, все имеют альтернативный текст.','%d label(s) translated.'=>'%d метка(и) переведена.','%d language not yet linked'=>'%d языков ещё не связаны' . "\0" . '%d языков ещё не связаны' . "\0" . '','%d link updated.'=>'Обновлена %d ссылка.' . "\0" . 'Обновлено %d ссылок.' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Не удалось автоматически удалить %d файлов локализации (установлено DISALLOW_FILE_MODS). Удалите их вручную через ваш сервер или WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Не удалось автоматически удалить %d файлов локализации (установлено DISALLOW_FILE_MODS). Удалите их вручную через ваш сервер или WP-CLI: wp language core uninstall <locale>.' . "\0" . '','%d locale file removed.'=>'Удалён %d файл локализации.' . "\0" . 'Удалено %d файлов локализации.' . "\0" . '','%d locale pack installed.'=>'Установлен %d пакет локализации.' . "\0" . 'Установлено %d пакетов локализации.' . "\0" . '','%d navigation reference updated.'=>'Обновлена %d навигационная ссылка.' . "\0" . 'Обновлено %d навигационных ссылок.' . "\0" . '','%d part reference updated.'=>'Обновлена %d ссылка на часть шаблона.' . "\0" . 'Обновлено %d ссылок на части шаблона.' . "\0" . '','%d post'=>'%d сообщение' . "\0" . '%d сообщений' . "\0" . '','%d rule registered'=>'Зарегистрировано %d правила' . "\0" . 'Зарегистрировано %d правил' . "\0" . '','%d template repaired.'=>'Исправлено %d шаблон(ов).' . "\0" . 'Исправлено %d шаблонов.' . "\0" . '','%d term(s) translated.'=>'Переведено %d термин(ов).','%d words.'=>'%d слов.','%s Archive'=>'%s Архив','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s активен и уже выводит JSON-LD Schema.org. Lingua Forge отключила собственный вывод схемы, чтобы избежать конфликтующих графов. В отличие от Open Graph — где LF добавляет og:locale поверх другого плагина — схема не может быть чисто дополнена: дублирующиеся или перекрывающиеся JSON-LD графы вызывают ошибки валидации. Отключите вывод схемы в обнаруженном плагине, если хотите, чтобы LF обрабатывал структурированные данные.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s активен и генерирует собственную карту сайта. Эта карта сайта отделена от карты LF. Обе должны быть отправлены в Google Search Console: карта сайта SEO-плагина содержит ваш контент; карта LF добавляет мультиязычные альтернативные ссылки. Карта LF автоматически объявляется в robots.txt.','(active)'=>'(активно)','(avg %.1f hits/block)'=>'(в среднем %.1f обращений/блок)','(avg %.1f hits/entry)'=>'(среднее %.1f ударов/запись)','(classic theme)'=>'(классическая тема)','(disabled)'=>'(отключено)','(FSE / block theme)'=>'(FSE / блочная тема)','(no title) #%d'=>'(без названия) #%d','(partial)'=>'(частично)','(server/FPM timeout still applies)'=>'(тайм-аут сервера/FPM все еще действует)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} не имели заменяемых ссылок — повторите сканирование для проверки)','.txt file(s) in the directory'=>'.txt файл(ы) в каталоге','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — подзаголовки H2 или H3 не найдены. Добавление H2 улучшает структуру.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — нет подзаголовков H2 (приемлемо для этого типа контента).','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — без H2, но найдено %d подзаголовков H3 (например, заголовки аккордеона/деталей). Структура приемлема.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — короткое содержание (%d параграфов), подзаголовки не обязательны.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d локализованный(ые) шаблон(ы) из темы &#8220;%2$s&#8221; сохранены в базе данных, но в настоящее время неактивны. Они снова станут активными, если вы повторно активируете эту тему. Чтобы перенести ваши переводы на новую тему, regenerated их через <strong>Настройки → Lingua Forge → Маршрутизатор → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> автоматически исправляемых ссылки','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> ссылок требуют ручной проверки','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> устаревший(ие) путь(и)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> проблема(ы) шаблона','_lf_lang Coverage'=>'Покрытие _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'На сайте существует физический файл robots.txt в корне. Виртуальный robots.txt WordPress — и Sitemap: фильтр LF — обходятся. Карта сайта LF не объявляется поисковым системам.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Принимаются только скомпилированные файлы .mo. Имя файла должно соответствовать шаблону {textdomain}-{locale}.mo. Загрузка файла с таким же именем, как существующий, заменит его.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Доступ запрещен — ваш аккаунт может быть заблокирован или ключ не имеет необходимых разрешений.','Action'=>'Действие','active'=>'активен','Active Languages'=>'Активные языки','Active languages'=>'Активные языки','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Активные языки: добавьте каждый язык, который вы хотите поддерживать. Каждый язык получает префикс URL или поддомен и тег hreflang в разделе &lt;head&gt; страницы.','Active Plugins'=>'Активные плагины','Active preset'=>'Активный пресет','Active Provider'=>'Активный поставщик','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Активный поставщик, настроенные ключи, выбор уровня модели, предустановка и дневная норма.','Active theme'=>'Активная тема','Active: %s.'=>'Активно: %s.','Add entry'=>'Добавить запись','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Добавьте инструкции для улучшения черновика — например, сделайте его короче, добавьте раздел с выводами, используйте более официальный стиль, включите блок FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Добавьте инструкции для улучшения черновика — например, сделайте его короче, добавьте раздел с выводом, используйте более формальный стиль…','Add key →'=>'Добавить ключ →','Add new entry'=>'Добавить новую запись','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Добавьте один термин на строку. Требуются как исходный термин, так и целевое отображение. Пара языков определяет, к каким заданиям перевода применяется ограничение.','Add Sitemap directive to robots.txt'=>'Добавьте директиву Sitemap в robots.txt','Add the following line to your robots.txt manually:'=>'Добавьте следующую строку в ваш robots.txt вручную:','Add WooCommerce product tags to Open Graph output'=>'Добавьте теги товаров WooCommerce в вывод Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Добавляет ссылку на главную страницу, чтобы посетители могли просматривать сайт на своем языке.','Administrators only (manage_options)'=>'Только администраторы (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'После изменения основного языка обновите постоянные ссылки (раздел ниже), чтобы обновить маршрутизацию URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'После изменения настроек структуры URL (префикс пути ↔ поддомен) всегда посещайте Настройки → Постоянные ссылки и нажимайте Сохранить изменения, чтобы сбросить правила переписывания.','AI analysis failed. Please try again.'=>'Анализ AI не удался. Пожалуйста, попробуйте снова.','AI Behaviour Preset'=>'Настройка поведения ИИ','AI cache cleared. %d entry was removed.'=>'Кэш ИИ очищен. Удалено записей: %d.' . "\0" . 'Кэш ИИ очищен. Удалено записей: %d.' . "\0" . '','AI Configuration'=>'Настройка ИИ','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Функции AI являются необязательными. Маршрутизация по языкам, hreflang, переключатель языков и система групп переводов работают без настроенного провайдера.','AI Limits & Security'=>'Ограничения и безопасность ИИ','AI Provider'=>'Поставщик ИИ','AI provider returned an empty response.'=>'Поставщик ИИ вернул пустой ответ.','AI Provider Tab'=>'Вкладка поставщика AI','AI Recommendations'=>'Рекомендации AI','AI returned an unexpected response format. Please try again.'=>'AI вернул неожиданный формат ответа. Пожалуйста, попробуйте снова.','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Перевод ИИ и пакетный анализ могут завершиться с тайм-аутом. Рекомендуется 120 секунд или более.','AI Usage'=>'Использование ИИ','AI Usage & Cache'=>'Использование AI и кэш','AI Usage & Cache Tab'=>'Вкладка использования AI и кэширования','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Цель — 120–160 символов. Оставьте пустым, чтобы использовать резервное копирование из аннотации.','All labels already translated.'=>'Все метки уже переведены.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Все основные поисковые системы — Google, Bing и Yandex — автоматически обнаруживают карту сайта через директиву Sitemap: в robots.txt. Не требуется ручное действие. Кнопки ниже отправляют мгновенный пинг, чтобы поисковик перепросмотрел карту сайта сейчас, а не ждал следующего запланированного проверки robots.txt.','All published posts have a _lf_lang value. No gaps detected.'=>'Все опубликованные сообщения имеют значение _lf_lang. Пробелов не обнаружено.','All template metadata is already up to date.'=>'Все метаданные шаблонов уже актуальны.','All time'=>'Все время','All types'=>'Все типы','Allow editors to lock individual blocks'=>'Разрешить редакторам блокировать отдельные блоки','Allow Gutenberg template-editing mode on post screens'=>'Разрешить режим редактирования шаблонов Gutenberg на страницах постов','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Также удалять назначения языков, отношения перевода, метаописания, глоссарий и кеш памяти перевода при удалении плагина.','Also generate meta description'=>'Также создать мета-описание','Alternative (server-side):'=>'Альтернатива (серверная сторона):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Всегда выводите только og:locale и og:locale:alternate. Используйте, когда другой плагин или тема управляют полным набором OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Всегда выводите полный набор OG + Twitter Card независимо от других плагинов. Используйте только, если другие плагины не выводят OG-теги.','An unknown error occurred.'=>'Произошла неизвестная ошибка.','Analyse'=>'Анализ','Analyse all languages'=>'Анализировать все языки','Analyse…'=>'Анализ…','Analysis'=>'Анализ','Analysis request failed. Please try again.'=>'Запрос анализа не удался. Пожалуйста, попробуйте снова.','Analyzing…'=>'Анализ…','and'=>'и','and set it to one of the active content languages listed above.'=>'и установите его на один из перечисленных выше активных языков контента.','Anthropic (Claude)'=>'Anthropic (Клод)','Anthropic Console'=>'Консоль Anthropic','any'=>'любой','API calls saved by cache'=>'API вызовы, сохраненные в кэше','API Key'=>'Ключ API','API Keys'=>'API-ключи','API Response Cache'=>'Кэш ответов API','API Response Cache setting saved.'=>'Настройка кеша ответов API сохранена.','Appends the following line to your existing robots.txt: %s'=>'Добавляет следующую строку в ваш существующий robots.txt: %s','Applied ✓'=>'Применено ✓','Apply failed — please try again.'=>'Не удалось применить — попробуйте еще раз.','Apply to all language versions'=>'Применить ко всем версиям языка','Apply to Block'=>'Применить к блоку','Apply to Editor'=>'Применить к редактору','Apply to Footnote'=>'Применить к сноске','Apply to Meta Description'=>'Применить к мета-описанию','Apply translation'=>'Применить перевод','Applying…'=>'Применение…','Approximate size'=>'Приблизительный размер','Archive'=>'Архив','Archive: %s'=>'Архив: %s','Article / WebPage'=>'Статья / Веб-страница','Article / WebPage — all singular posts and pages'=>'Статья / Веб-страница — все единственные посты и страницы','Attribute label displayed in this language. Leave empty to use the default label.'=>'Метка атрибута, отображаемая на этом языке. Оставьте пустым, чтобы использовать метку по умолчанию.','Authors and above (edit_published_posts)'=>'Авторы и выше (edit_published_posts)','Auto (recommended)'=>'Автоматически (рекомендуется)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Автоматическое определение назначений: продукты WooCommerce → профиль продукта; статическая главная страница → посадочный профиль; все остальное → блог. Выберите конкретный профиль, чтобы переопределить это для всех сообщений.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Автоматически определено для статической главной страницы; можно выбрать вручную. Заголовок 20 баллов · Мета-описание 30 баллов · Количество слов 15 баллов · Заголовки 10 баллов · Изображения 15 баллов · Ссылки 0 баллов. Ограничение SERP для заголовка 70 символов; предупреждение при менее 150 слов, ошибка при менее 60; H2 и внутренние ссылки необязательны.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Автоматически определено для продуктов WooCommerce. Заголовок 20 баллов · Мета-описание 30 баллов · Количество слов 15 баллов · Заголовки 5 баллов · Изображения 20 баллов · Ссылки 0 баллов. Ограничение SERP для заголовка 70 символов; предупреждение при менее 80 слов, ошибка при менее 40; H2 и внутренние ссылки необязательны.','Available models reference'=>'Ссылка на доступные модели','avg'=>'среднее','Batch Analysis'=>'Пакетный анализ','Behavior'=>'Поведение','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Поведение: выберите пресет AI (Literal, Balanced, Creative), добавьте глобальные инструкции для сайта, включите или отключите автоматический перевод при сохранении поста и настройте Память переводов.','Block Content'=>'Блок содержимого','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Отображает вежливое уведомление, когда текущая страница показывается на исходном языке, потому что для языка посетителя перевод отсутствует. Управляется сигналом LINGUAFORGE_LANG_FALLBACK_ACTIVE маршрутизатора Lingua Forge — ничего не выводит, когда для запрошенного языка есть перевод.','Block Editor'=>'Редактор блоков','block keywordfallback'=>'запасной вариант','block keywordi18n'=>'i18n','block keywordlanguage'=>'язык','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'перевод','Block locking'=>'Блокировка','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Шаблоны блоков, зарегистрированные для пользовательских типов записей. Используйте кнопку Перевести для создания варианта на другом языке. Переведённый контент сохраняется здесь и может быть скопирован в любой пост CPT через вставщик шаблонов редактора блоков или использован как отправная точка для синхронизированного шаблона (многоразовый блок).','block titleMissing Translation Notice'=>'Уведомление о пропущенном переводе','Block translation reuses'=>'Повторное использование блоков перевода','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Кеш переводов на уровне блока, общий для сообщений. При включении одинаковые блоки (одинаковый разметка, пара языков и глоссарий) обслуживаются из памяти вместо повторного вызова ИИ. Редактирование глоссария и изменение пресета Совместимости автоматически аннулируют соответствующие кешированные переводы.','Blog / Editorial'=>'Блог / Редакция','Blog / Editorial (default)'=>'Блог / Редакция (по умолчанию)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Блоги используют Article; все остальные типы постов и страницы используют WebPage. Включает заголовок, описание, inLanguage, url, datePublished, dateModified, изображение и издателя.','Browser language redirect'=>'Перенаправление по языку браузера','Built-in preset instructions:'=>'Встроенные предустановленные инструкции:','Bulletize (•-prefixed)'=>'Создать список (с маркерами •-)','cached'=>'кэшировано','Cached API responses'=>'Кэшированные ответы API','Cached block translations'=>'Кэшированные переводы блоков','Cancel'=>'Отмена','Cannot determine target language from slug.'=>'Невозможно определить целевой язык по слагу.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Невозможно записать в продукт %1$d: это переводная версия (язык: %2$s)%3$s. Операционные данные (цена, наличие, SKU, размеры) должны обновляться в исходном продукте. Определите ID исходного продукта через: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Канонический тег','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ограничьте использование ИИ на сайте и ограничьте роли пользователей, которые могут запускать платные вызовы ИИ. Расположено поверх ограничения по количеству запросов на пользователя (30 запросов / минута, жестко задано), которое уже защищает от бесконтрольных циклов одного пользователя.','Cart'=>'Корзина','chars'=>'символов','Check your account, billing, or remaining credits directly on the provider console:'=>'Проверьте свой аккаунт, биллинг или оставшиеся кредиты прямо в консоли провайдера:','Checkout'=>'Оформление заказа','Chunk translated'=>'Фрагмент переведен','Chunk translated to:'=>'Фрагмент переведен в:','Clear'=>'Очистить','Clear All'=>'Очистить всё','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Очистить все кэшированные результаты ИИ? В будущем запросы вызовут новые API-запросы, пока кэш не будет перестроен.','Clear API Response Cache'=>'Очистить кэш ответов API','Clear Debug Files'=>'Очистить файлы отладки','Clear hints'=>'Очистить подсказки','Clear input'=>'Очистить ввод','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Очистить весь кеш памяти перевода? Будущие переводы будут заново строить кеш по мере выполнения.','Clear Translation Memory'=>'Очистить кеш памяти перевода','Close'=>'Закрыть','Close language panel'=>'Закрыть панель языков','Close popover'=>'Закрыть всплывающее окно','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Раскрывающийся дамп всех записей LF в $wp_rewrite->extra_rules_top. Полезно для диагностики ошибок 404 или конфликтов маршрутизации после добавления нового языка.','Compatibility'=>'Совместимость','Compliance Preset'=>'Предустановка соответствия','Configuration issue: WP site language is not a content language'=>'Проблема конфигурации: язык сайта WP не является языком контента.','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Настройте поставщика AI в Настройки → API-ключи для включения рекомендаций на базе AI.','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Настройка hreflang, Open Graph, Schema.org, карты сайта и социальных сетей для каждого языка на вашем сайте. Каждый раздел ниже отвечает за один аспект мультиязыкового SEO.','Configured'=>'Настроено','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Подтверждает, что структура постоянных ссылок совместима с маршрутизацией путей Lingua Forge. Простые и числовые структуры не поддерживаются.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Контактная форма 7 (wpcf7_contact_form), контакты Flamingo и входящие сообщения (flamingo_contact, flamingo_inbound), а также хранилище синхронизации пакета языка WordPress (wp_sync_storage) исключены автоматически. Добавьте любые другие сторонние типы записей, содержимое которых не должно фильтроваться по языкам, по одному в строке или через запятую.','Content generated'=>'Контент сгенерирован','Content Generator'=>'Генератор контента','Content profiles and weights'=>'Профили контента и веса','Content ready'=>'Контент готов','Contributors and above — default (edit_posts)'=>'Соавторы и выше — по умолчанию (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Контролируйте, сколько контента отправляется в ИИ и насколько большим может быть ответ. Оставьте поле пустым, чтобы использовать встроенное значение по умолчанию (показано как заполнитель). Увеличьте эти значения, если большие страницы обрезаются; уменьшите — чтобы снизить затраты на API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Управляет бюджетом токенов и лимитами ввода для функции генерации контента ИИ. Оставьте поля пустыми, чтобы использовать встроенные значения по умолчанию.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Управляет тем, что происходит, когда администратор удаляет плагин из Plugins → Installed Plugins → Delete. Настройки плагина и кеши AI всегда удаляются. Назначения языков и отношения перевода по умолчанию сохраняются, чтобы случайное удаление или повторная установка могли продолжить работу с того места, где остановились.','Conversational'=>'Разговорный','Copied ✓'=>'Скопировано ✓','Copied!'=>'Скопировано!','Copy'=>'Копировать','Copy and paste into a GitHub issue or support request.'=>'Скопируйте и вставьте в проблему GitHub или запрос поддержки.','Copy failed — please copy the URL manually.'=>'Копирование не удалось — пожалуйста, скопируйте URL вручную.','Copy markup'=>'Копировать разметку','Copy system info'=>'Копировать системную информацию','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Скопировать текущий URL в буфер обмена. При успешном копировании отображается сообщение "Ссылка скопирована".','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Скопируйте результат и вставьте туда, где нужно (например, прямо в поле сноски).','Copy to safe storage'=>'Копировать в безопасное хранилище','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'копировать/встроенные/автоматические действия JS: обрабатываются social-share.js LF','Could not add entry: source term and target term are required.'=>'Не удалось добавить запись: требуются исходный термин и целевой термин.','Could not copy the file. Check that the uploads folder is writable.'=>'Не удалось скопировать файл. Проверьте, что папка uploads доступна для записи.','Could not instantiate the provider.'=>'Не удалось создать экземпляр поставщика.','Could not save the file. Check that the uploads folder is writable.'=>'Не удалось сохранить файл. Проверьте, что папка uploads доступна для записи.','Could not save the glossary entry.'=>'Не удалось сохранить запись в глоссарии.','Could not write to robots.txt. Check file permissions.'=>'Не удалось записать в robots.txt. Проверьте разрешения файла.','CPT Block Patterns'=>'Шаблоны блоков CPT','Create'=>'Создать','Create missing'=>'Создать отсутствующее','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Создание переводов для типа поста "%s" требует активной интеграции. Пожалуйста, убедитесь, что необходимая интеграция установлена и активирована.','Creating…'=>'Создание…','Creative / Marketing'=>'Креативный / Маркетинг','Creative / Marketing instructions'=>'Креативные / маркетинговые инструкции','Current content (will be overwritten)'=>'Текущее содержание (будет перезаписано)','Current status'=>'Текущий статус','Current title'=>'Текущий заголовок','Current: {current}'=>'Текущий: {current}','Currently emitting'=>'В настоящее время передается','Currently inherited from the %s constant. Selecting a value here will override it.'=>'В настоящее время наследуется от константы %s. Выбор значения здесь переопределит её.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'В настоящее время пропускается для постов, использующих заполнители атрибутов блок-комментариев (wp:details, поля сводки и т. д.) — они переходят к существующему однократному пути перевода.','Currently:'=>'В настоящее время:','Custom'=>'Пользовательский','Custom tables — LF post-meta filters do not affect orders.'=>'Пользовательские таблицы — фильтры LF пост-мета не влияют на заказы.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Дневной лимит запросов к ИИ достигнут (%1$d запросов). Обновление в %2$s UTC.','Daily quota'=>'Ежедневная квота','Daily request limit'=>'Ежедневный лимит запросов','Danger Zone'=>'Опасная зона','Debug Files'=>'Файлы отладки','Debug files cleared. %d file was removed.'=>'Файлы отладки очищены. Удален %d файл.' . "\0" . 'Файлы отладки очищены. Удалено %d файлов.' . "\0" . '','Debug Info'=>'Отладочная информация','Debug logging'=>'Ведение журнала отладки','Debug logging disabled.'=>'Ведение журнала отладки отключено.','Debug logging enabled.'=>'Ведение журнала отладки включено.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Отладка: включите журнал отладки для захвата подсказок AI и ответов API в локальный файл. Отключите после устранения проблем — режим отладки записывает файл при каждом запросе AI.','Default OG image'=>'Стандартное изображение OG','Default profile'=>'Стандартный профиль','Delete'=>'Удалить','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Удалить все .txt файлы в каталоге отладки? Сам каталог останется, чтобы будущие записи отладки могли сохраняться без проблем.','Delete all files for this override (both .mo and .po)?'=>'Удалить все файлы для этого переопределения (оба .mo и .po)?','Delete content data on uninstall'=>'Удалить данные контента при удалении','Delete this glossary entry?'=>'Удалить эту запись из глоссария?','Describe what to write — topic, key points, structure…'=>'Опишите, что писать — тема, ключевые моменты, структура…','Destructive action — read before proceeding'=>'Деструктивное действие — прочтите перед продолжением','Details ↗'=>'Подробнее ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Обнаружение активных SEO-плагинов (Yoast, Rank Math и др.) во время выполнения. Передавайте только og:locale + og:locale:alternate, когда другой плагин уже выводит полный набор OG; передавайте полный набор, когда ни один не обнаружен.','Directory'=>'Каталог','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Отключить только для безголовых сайтов или полностью настраиваемых реализаций hreflang. При отключении LF больше не удаляет канонический тег WordPress и не подавляет вывод hreflang SEO-плагинов.','Disabled'=>'Отключено','Disabled (by setting)'=>'Отключено (установка)','Disabled (mode setting)'=>'Отключено (настройка режима)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Отключено, потому что плагин lf-social-share уже обеспечивает эту функцию.','DISALLOW_FILE_MODS is set.'=>'Установлено DISALLOW_FILE_MODS.','Display'=>'Отображение','Displays the Lingua Forge language switcher.'=>'Отображает переключатель языков Lingua Forge.','Do not output any OG tags.'=>'Не выводить теги OG.','Documentation'=>'Документация','Done'=>'Готово','Done — {done} of {total} post(s) fixed.'=>'Готово — исправлено {done} из {total} постов.','Down'=>'Вниз','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Загрузите и установите пакет языка ядра WordPress напрямую с WordPress.org. После установки локаль станет доступной для маршрутизации URL и рабочего процесса перевода AI. Список доступных языков загружается по требованию — нажмите кнопку ниже, чтобы загрузить его.','Dropdown direction'=>'Направление выпадающего меню','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Каждая метрика дает один из четырех статусов: ok (полный вес), warn (50 % веса), fail (0), или info (0, без штрафа). Оценка ≥ 80 — зеленый, 50–79 — янтарный, ниже 50 — красный.','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Каждый пост оценивается по шкале от 0 до 100 на основе шести правил: заголовок, мета-описание, количество слов, структура заголовков, покрытие alt изображений и внутренние ссылки. За время чтения всегда начисляется 10 очков (только для информации). Остальные 90 очков распределяются по другим метрикам с весами, зависящими от профиля контента (см. ниже).','edit'=>'редактировать','Editors and above (edit_others_posts)'=>'Редакторы и выше (edit_others_posts)','Enable API response caching'=>'Включить кеширование ответов API','Enable block-level translation cache reuse across posts'=>'Включить повторное использование кэша перевода на уровне блоков между постами','Enable Social Share URL rewriting for Social Icons blocks'=>'Включить переписывание URL для социальных иконок блоков','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Включите, когда ваша тема отображает заголовок поста как H2 вместо H1 (часто в некоторых блоковых темах). Анализатор получает страницу и, если не находит H1, но обнаруживает H2, он повышает первый H2 до H1 для оценки.','Environment'=>'Окружающая среда','environment variable'=>'переменная окружения','Error'=>'Ошибка','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Каждый раз при анализе поста его оценка сохраняется в мета-данных поста. В колонке языка списка постов отображается цветовая метка "SEO N" для любого поста, который был проанализирован хотя бы один раз. Когда сохраняется две оценки, отображается индикатор дельты (↑N / ↓N), показывающий изменение с предыдущего запуска.','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Требуется ровно один H1. Обычно H1 — это заголовок поста, отображаемый темой — он читается с живой страницы, если возможно, и из содержимого поста как резервный вариант.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Пример поддерживаемой конфигурации: язык сайта WP = CA (каталанский), языки контента = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Пример неподдерживаемой конфигурации: язык сайта WP = EN (английский), языки контента = CA + ES только. Английский не является языком контента, поэтому Lingua Forge не может сопоставить локаль WP с какой-либо группой переводов.','Exclude from navigation menus'=>'Исключить из навигационных меню','Exclude from routing'=>'Исключить из маршрутизации','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Исключить этот тип поста из маршрутизации по языкам — его посты больше не будут отображаться здесь или получать _lf_lang. Это нельзя отменить автоматически.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Исключить этот тип поста из маршрутизации по языкам? Его посты больше не будут отображаться в этом списке или получать _lf_lang. Вы можете отменить это в Настройках → Маршрутизатор → Исключения фильтра запросов.','excluded from routing'=>'исключено из маршрутизации','Excluded post types'=>'Исключенные типы постов','Excluding…'=>'Исключение…','Expand'=>'Расширить','Expected: {expected}'=>'Ожидаемый: {expected}','External share services'=>'Внешние сервисы обмена','Extra guidance — tone, style, constraints, target audience…'=>'Дополнительные рекомендации — тон, стиль, ограничения, целевая аудитория…','Extra guidance — tone, style, constraints…'=>'Дополнительные рекомендации — тон, стиль, ограничения…','Failed to save exclusion.'=>'Не удалось сохранить исключение.','Failed. Please try again.'=>'Не удалось. Пожалуйста, попробуйте снова.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL запасного изображения, используемый, когда у страницы нет избранного изображения, логотипа сайта или иконки сайта. Показывается в социальных превью для архивов, индекса блога и любой отдельной страницы без миниатюры.','Feature'=>'Функция','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Функции сгруппированы в два уровня. Введите точный идентификатор модели для каждого уровня и поставщика. Оставьте поле пустым, чтобы использовать встроенное значение по умолчанию (отображается как заполнитель). Только модели активного поставщика вызываются во время выполнения — настройте остальные заранее, если планируете переключение.','File copied to safe storage successfully.'=>'Файл успешно скопирован в безопасное хранилище.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Модификации файлов отключены (DISALLOW_FILE_MODS).','Files'=>'Файлы','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Файлы сохраняются в указанной ниже директории. Полезно для диагностики проблем с переводом — отключите после получения нужных данных, чтобы файлы не накапливались. Также можно принудительно установить это через wp-config.php с помощью `define( \'LINGUAFORGE_AI_DEBUG\', true );`, что переопределяет переключатель.','Filter'=>'Фильтр','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Фильтрация по языку и типу поста, просмотр контента и запуск анализа по любой позиции для проведения SEO-аудита на основе правил — длина заголовка, мета-описание, количество слов, структура заголовков, покрытие alt изображений и внутренние ссылки.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Используйте фильтр с linguaforge_debug_dir для перенаправления вывода отладки в недоступное для публики место.','Finding'=>'Поиск','Fix'=>'Исправить','Fix All'=>'Исправить всё','Fix all links'=>'Исправить все ссылки','Fix all parts'=>'Исправить все части','Fix Links'=>'Исправить ссылки','Fix Nav'=>'Исправить навигацию','Fix Parts'=>'Исправить части','Fix Template'=>'Исправить шаблон','Fix: go to'=>'Исправить: перейти к','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Исправляет пространство имен редактора сайта и тег _lf_lang для всех шаблонов FSE, созданных с помощью LF, хранящихся в базе данных. Запустите это один раз после обновления с более ранней версии Lingua Forge — оно перемещает шаблоны, полученные из WooCommerce, из группы активной темы в группу WooCommerce в редакторе сайта, и обеспечивает обнаружение всех шаблонов для отчетов о покрытии.','Fixing {n} / {total}…'=>'Исправление {n} / {total}…','Fixing…'=>'Исправление…','Flush Permalink Rules'=>'Обновить правила постоянных ссылок','Flush Permalinks'=>'Обновить постоянные ссылки','Flush Sitemap Cache'=>'Очистить кеш карты сайта','Footnote Content'=>'Содержание сноски','footnote(s) translated — applied together with content.'=>'переведены сноски — применены вместе с содержимым.','Footnotes'=>'Сноски','Footnotes payload (advanced)'=>'Дополнительные сноски (расширенные)','Forbidden'=>'Запрещено','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Принудительно ВЫКЛЮЧЕНО с помощью константы LINGUAFORGE_AI_DEBUG в wp-config.php. Удалите эту строку, чтобы управлять этим переключателем отсюда.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Принудительно ВКЛЮЧЕНО с помощью константы LINGUAFORGE_AI_DEBUG в wp-config.php. Удалите эту строку, чтобы управлять этим переключателем отсюда.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Принудительно регенерировать карту сайта при следующем запросе. Используйте после массового импорта или ручного редактирования связей переводов.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Обнаружена ошибка или неожиданное поведение? Пожалуйста, откройте проблему на GitHub — включите блок информации для отладки и краткое описание того, что вы ожидали и что произошло.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Обнаружено {parts} в <strong>{total}</strong> из <strong>{scanned}</strong> просканированных постов для <strong>{lang}</strong>.','From'=>'От','Front Page'=>'Главная страница','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Локализация FSE: создавайте каркасы, переводите и исправляйте ссылки в шаблонах и частях шаблонов полного редактирования сайта прямо из этой вкладки.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Шаблоны FSE, созданные из активной темы. Создавайте и настраивайте в редакторе сайта.','Full'=>'Полный','Full Article'=>'Полная статья','Full post'=>'Полный пост','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Перевод всей страницы, Генератор контента (модели среднего уровня полностью достаточны)','General'=>'Общее','Generate'=>'Создать','Generate Content'=>'Генерировать контент','Generate content…'=>'Генерация контента…','Generate Excerpt'=>'Создать выдержку','Generate Meta Description'=>'Создать мета-описание','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Генерировать многоязыковую карту сайта по адресу /lf-sitemap.xml','Generated Content'=>'Сгенерированный контент','Generated meta description'=>'Сгенерированное мета-описание','Generating…'=>'Генерация…','Generation failed.'=>'Не удалось сгенерировать.','Getting started'=>'Начало работы','Global AI preset'=>'Глобальная предустановка ИИ','Global default (%s)'=>'Глобальные настройки по умолчанию (%s)','Glossary'=>'Глоссарий','Glossary entry added.'=>'Запись в глоссарии добавлена.','Glossary entry removed.'=>'Запись в глоссарии удалена.','Glossary Tab'=>'Вкладка Глоссарий','Google (Gemini)'=>'Google (Gemini)','Google AI Studio'=>'Google AI Studio','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Включен режим H2 как H1 — заголовок считается эквивалентом H1. (Теги заголовков не могут быть обнаружены на отображаемой странице; убедитесь, что ваша тема правильно выводит заголовок.)','Heading structure rules'=>'Правила структуры заголовков','Headings'=>'Заголовки','Hide'=>'Скрыть','High-Performance Order Storage (HPOS)'=>'Высокопроизводительное хранение заказов (HPOS)','Hints'=>'Подсказки','Home link text'=>'Текст ссылки на главную','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Как она должна выглядеть в переводе. Введите то же значение, что и исходный термин, чтобы указать ИИ сохранить его дословно.','How to use'=>'Инструкция по использованию','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT синхронизированы — переходный режим; фильтры LF пост-мета применяются к копии CPT.','Hreflang'=>'Hreflang','Hreflang output'=>'Вывод hreflang','Hreflang settings saved.'=>'Настройки hreflang сохранены.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Иконка + метка','Icon only'=>'Только иконка','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Если установлено, удаление плагина навсегда удалит все назначения языков, отношения перевода, метаописания, пресеты для страниц, глоссарий AI и кеш памяти перевода для каждого поста на этом сайте. Это действие нельзя отменить. Не ставьте галочку, если вы полностью удаляете мультиязычную поддержку сайта.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Если у вас установлен общий SEO-плагин, эта панель показывает, как LF адаптируется, чтобы избежать дублирования вывода. Цель — избегать конфликтов, а не сотрудничества. LF всегда обеспечивает многоязыковый слой SEO (hreflang, og:locale, inLanguage schema), который требует знания конфигурации маршрутизации LF для правильного вывода.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Если у вас установлен Yoast SEO, Rank Math, All in One SEO или SEOPress, Lingua Forge обнаружит их и адаптируется, чтобы избежать дублирования. Для hreflang LF полностью берет управление и подавляет вывод плагина, потому что эти плагины не могут правильно генерировать hreflang для многоязычной маршрутизации. Для Open Graph LF добавляет только og:locale и og:locale:alternate — многоязычные сигналы, которые плагин не может обеспечить — и оставляет базовый набор OG на усмотрение плагина. Для Schema.org LF полностью отключает свой вывод, чтобы избежать конфликтующих графов JSON-LD.','Images'=>'Изображения','Improve writing'=>'Улучшить написание','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'В редакторе блоков добавьте блок социальных иконок. Для каждой иконки откройте настройки ссылки и введите одно из значений "share:" ниже в качестве URL. На фронтенде LF заменяет его на правильный URL для обмена для текущей страницы.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Включает название, описание, inLanguage, url, изображение и предложение с ценой, валютой и доступностью. Цена и доступность берутся из продукта исходного языка (модель совместного запаса).','Includes site name, url, and inLanguage.'=>'Включает название сайта, url и inLanguage.','Informative'=>'Информативный','Input tokens'=>'Входные токены','Install'=>'Установить','Install a Language'=>'Установить язык','Installed SEO plugins'=>'Установленные SEO-плагины','Installing…'=>'Установка…','instock / oos / pending from WC stock status'=>'в наличии / нет в наличии / ожидает по статусу WC','Instructions (optional)'=>'Инструкции (опционально)','Instructions / key points'=>'Инструкции / ключевые моменты','Insufficient permissions.'=>'Недостаточно прав.','Integration API'=>'Интеграционный API','Internal Link Fixer'=>'Исправитель внутренних ссылок','Introduction only'=>'Только введение','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Недопустимый API-ключ — перепроверьте введенный ключ в настройках провайдера AI.','Invalid file reference.'=>'Недопустимая ссылка на файл.','Invalid filename.'=>'Недопустимое имя файла.','Invalid language code.'=>'Недопустимый код языка.','Invalid language.'=>'Недопустимый язык.','Invalid locale code.'=>'Недопустимый код локали.','Invalid or primary language.'=>'Недопустимый или основной язык.','Invalid post ID.'=>'Недопустимый ID поста.','Invalid post type.'=>'Недопустимый тип поста.','Invalid taxonomy.'=>'Недопустимая таксономия.','Invalid template part.'=>'Недопустимая часть шаблона.','Invalid template type.'=>'Недопустимый тип шаблона.','JavaScript-powered actions'=>'Действия на базе JavaScript','Just now'=>'Только что','Key points, ideas, or structure to build from…'=>'Ключевые моменты, идеи или структура, на которых нужно строить…','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Ключи шифруются в состоянии покоя с помощью AES-256-GCM с секретом, уникальным для сайта (LINGUAFORGE_SECRET). Не делитесь экспортами базы данных без предварительной ротации секрета.','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Ключи API шифруются с помощью AES-256-CBC перед сохранением в базе данных WordPress. Секрет шифрования берется из ваших солей авторизации WordPress (wp-config.php), поэтому открытые ключи никогда не попадают в базу данных.','Landing / Short-form'=>'Лендинг / Краткая форма','Language'=>'Язык','Language %s installed successfully.'=>'Язык %s успешно установлен.','Language (optional)'=>'Язык (опционально)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Установка языков отключена на этом сервере (установлена константа DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Установка языков отключена на этом сервере. В файле wp-config.php установлена константа DISALLOW_FILE_MODS. Установите языковые пакеты вручную через WP-CLI: wp language core install de_DE','Language label'=>'Метка языка','Language Overrides'=>'Переопределение языка','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Переопределения языка: управляйте пользовательскими файлами .po/.mo для строк интерфейса Lingua Forge. Используйте это вместо редактирования файлов плагина — переопределения сохраняются при обновлениях.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Не удалось установить языковой пакет. Язык может уже быть установлен, код локали может быть неправильным, или ваш сервер блокирует запись файлов.','Language Setup'=>'Настройка языка','Language Switcher'=>'Переключатель языков','Language switcher'=>'Переключатель языков','Language uninstalled. %d post deleted.'=>'Язык удален. Удалено %d постов.' . "\0" . 'Язык удален. Удалено %d постов.' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Копии шаблонов темы, специфичные для языка. После создания шаблонов они обновляются для ссылки на языковую часть.','Language:'=>'Язык:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Языки, в настоящее время известные маршрутизатору (полученные из установленных пакетов локализации WordPress и основного языка). Установите дополнительные языковые пакеты в разделе ниже, чтобы сделать больше языков доступными для маршрутизации и перевода.','Last 30 days'=>'Последние 30 дней','Last 7 days'=>'Последние 7 дней','Last generated: %s'=>'Последняя генерация: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Последний балл SEO на основе правил. Запустите анализ в Настройки → SEO → Анализ для обновления.','Last run: %s ago'=>'Последний запуск: %s назад','Lead paragraph (≤60 w)'=>'Вводный параграф (≤60 слов)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Оставьте поле модели пустым, чтобы использовать встроенное значение по умолчанию для этого уровня. Текст-заполнитель показывает, какая модель будет использоваться.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Оставьте пустым для названий брендов и терминов, не зависящих от языка, которые должны сохраняться независимо от языка перевода.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Оставьте пустым, чтобы применить эту запись ко всем целевым языкам — идеально для названий брендов, аббревиатур и терминов, которые должны сохраняться дословно в каждом переводе.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Оставьте пустым, чтобы сохранить существующий ключ. Введите новое значение для его замены.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Оставьте пустым, чтобы использовать встроенное значение по умолчанию. Очистка сохранённого переопределения восстанавливает значение по умолчанию при следующем сохранении.','Legacy lf-social-share mu-plugin'=>'Устаревший плагин lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Обнаружен устаревший плагин lf-social-share. LF передает базовый набор OG в этот плагин и выводит только og:locale + og:locale:alternate. Вы можете деактивировать плагин — встроенные функции LF (вкладка SEO → Социальные сети) и Open Graph обеспечивают ту же функциональность.','Legacy post-based (CPT)'=>'Наследственный пост (CPT)','Legal / Compliance'=>'Юридический / Соответствие','Legal / Compliance instructions'=>'Юридические / нормативные инструкции','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF всегда добавляет og:locale и og:locale:alternate — многоязычные OG-сигналы, которые не может правильно сгенерировать ни один SEO-плагин. Для базового набора OG (og:title, og:description, og:image) LF выводит его, когда других плагинов нет. Если установлен SEO-плагин, LF пропускает базовый набор, чтобы избежать дублирования тегов — не потому, что плагин "лучше", а потому, что дублирование не дает ценности.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF генерирует свою собственную карту сайта с альтернативами xhtml:link для всех групп переводов. Когда установлен SEO-плагин, он создает отдельную карту сайта — оба файла существуют независимо. Отправьте оба в Google Search Console: карту сайта SEO-плагина для обнаружения контента и карту LF для сигналов о языковых связях.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF выводит теги hreflang и удаляет канонический тег WordPress на многоязычных страницах.','LF is suppressing hreflang output from: %s'=>'LF подавляет вывод hreflang из: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF выводит точные hreflang для каждого настроенного языка, включая x-default. Общие SEO-плагины не имеют доступа к вашей конфигурации маршрутизации LF и будут создавать hreflang на основе неправильных предположений о URL. LF подавляет их вывод через фильтр, чтобы избежать конфликтов.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF выводит многоязычный JSON-LD с аннотациями inLanguage, связанными с его конфигурацией маршрутизации языков. Когда установлен SEO-плагин, LF полностью отключает свою схему: дублирующие графы JSON-LD вызывают ошибки валидации, и нет чистого способа дополнить существующий граф.','LF provides'=>'LF предоставляет','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF удаляет канонический тег WordPress на многоязычных страницах, потому что правила переписывания с префиксом языка маршрутизатора и hreflang x-default являются правильными каноническими сигналами для многоязычного сайта. Это предотвращает двойной канонический тег, если также выводит его SEO-плагин. LF не добавляет свой собственный канонический тег — маршрутизация по языкам уже делает каждый URL каноническим.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Записи, принадлежащие LF, в настоящее время зарегистрированы в $wp_rewrite->extra_rules_top. Полезно для диагностики ошибок 404 или конфликтов маршрутизации. Скопируйте их при подаче отчета об ошибке.','Light'=>'Лёгкий','Light (default — fast and cost-effective)'=>'Легкий (по умолчанию — быстрый и экономичный)','Light (fast and cost-effective — Haiku / Flash)'=>'Легкий (быстрый и экономичный — Haiku / Flash)','Light model'=>'Легкая модель','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Легкий: используется для метаописаний и генерации выдержек — быстро, недорого.','Limit results to pages in the given Lingua Forge language code.'=>'Ограничить результаты страницами с указанным кодом языка Lingua Forge.','Limits'=>'Лимиты','Lingua Forge'=>'Лингва Фордж','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge добавляет многоязычную маршрутизацию, перевод с помощью AI, SEO теги hreflang и переключатель языков на ваш сайт WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge добавляет свойства Open Graph, специфичные для WooCommerce, на страницы товаров, чтобы при обмене URL товара в Facebook, Pinterest и подобных платформах отображался правильный тип товара, цена и наличие.','Lingua Forge AI Tools'=>'Инструменты Lingua Forge AI','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge расширяет блок социальных иконок WordPress Core с динамическими URL-адресами для обмена. Установите ссылку любого значка на значение "share:", и LF перепишет его на правильный URL для обмена или действие JavaScript при отображении — без необходимости писать пользовательский код или использовать сторонний плагин.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge генерирует отдельную XML-карту сайта по адресу /lf-sitemap.xml, которая добавляет альтернативные языковые ссылки для всего вашего переведенного контента. Эта карта сайта дополняет карту сайта ядра WordPress и любую карту сайта SEO-плагина — она не заменяет их.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge — это полноценное решение для многоязычного SEO. Не требуется дополнительный SEO-плагин.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge — это полноценное решение для многоязычного SEO. Не требуется дополнительный SEO-плагин или плагин карты сайта.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge выводит теги <link rel="alternate" hreflang> для каждого настроенного языка на каждой странице, включая x-default, указывающий на исходный язык. Это основной сигнал мультиязычного SEO для Google и других поисковых систем — дополнительных SEO-плагинов не требуется.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge выводит метатеги Open Graph и Twitter Card, чтобы при обмене URL отображался правильный язык, заголовок, описание и изображение в социальных сетях.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge выводит структурированные данные Schema.org JSON-LD, чтобы поисковые системы понимали тип вашего контента, язык и метаданные. Это основной способ передачи аннотаций inLanguage для многоязычного контента Google и другим краулерам.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge по умолчанию ограничивает две функции Gutenberg, чтобы сохранить согласованное редакционное поведение во всех языках. Включите здесь, если вам нужны полные возможности Gutenberg / FSE.','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge ограничивает вторичные экземпляры WP_Query (виджеты боковой панели, шаблонные блоки, поиск плагинов) активным языком, внедряя ограничение _lf_lang в мета-данные. Типы постов, перечисленные здесь, исключены из этого ограничения — их запросы всегда не фильтруются.','Lingua Forge Settings'=>'Настройки Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge использует два независимых уровня кеширования, чтобы избежать избыточных вызовов API AI. Используйте вкладки ниже для проверки и управления каждым из них.','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge использует два независимых слоя кэширования для уменьшения повторных вызовов API AI:','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge использует два уровня моделей для каждого провайдера:','Lingua Forge version'=>'Версия Lingua Forge','Lingua Forge — Quick Translate'=>'Лингва Фордж — Быстрый перевод','Lingua Forge — Settings'=>'Lingua Forge — Настройки','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Встроенные модули Social Share и Open Graph Lingua Forge покрывают всю функциональность, предоставляемую mu-плагином, плюс поддержку многоязычного og:locale. Вы можете безопасно отключить mu-плагин.','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Версии Lingua Forge, WordPress и PHP; активная тема; структура URL; язык сайта WP и основной язык контента. Красный индикатор рядом с языком сайта WP означает, что он не является одним из активных языков контента — исправьте это в Настройках → Общие.','Link copied'=>'Ссылка скопирована','link(s)'=>'ссылка(и)','Links'=>'Ссылки','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Перечисляет активные сторонние плагины SEO. Lingua Forge адаптирует свой вывод при их наличии — см. Настройки → SEO → Совместимость для разбивки по функциям.','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Перечисляет типы записей, у которых есть опубликованные посты без мета-значения _lf_lang. Посты без этого тега невидимы для всех языковых фильтров. Используйте кнопку Исправить, чтобы пометить их исходным языком, или Исключить, чтобы полностью исключить тип записи из маршрутизации по языкам.','Load available languages'=>'Загрузить доступные языки','Load content'=>'Загрузить контент','Loaded from cache.'=>'Загружено из кеша.','Loading…'=>'Загрузка…','Locale only'=>'Только локаль','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Заблокировано — активен конфликтующий SEO-плагин. См. уведомление выше.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate сохраняет свои пользовательские переводы в wp-content/languages/loco/ — расположение, которое может быть тихо удалено обновлением ядра WP, переустановкой плагина или удалением самого Loco Translate. Копирование файлов сюда перемещает их в каталог Lingua Forge i18n-overrides, который сохраняется при всех этих событиях и загружается автоматически при каждом запросе.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — копировать в безопасное хранилище','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Наименьшая возможность WordPress, позволяющая запускать функции ИИ. Ужесточение этого ограничения на сайтах с несколькими авторами предотвращает запуск платных вызовов ИИ со стороны соавторов или пробных аккаунтов. Переопределяется для каждой функции через фильтр linguaforge_required_capability.','Maintenance'=>'Обслуживание','Maintenance Tab'=>'Вкладка Обслуживание','Make casual'=>'Сделать неформальным','Make concise'=>'Сделать кратким','Make formal'=>'Сделать формальным','Manage your account, review usage, or top up credits:'=>'Управляйте своим аккаунтом, просматривайте использование или пополняйте кредиты:','Mark citations needed'=>'Отметить необходимость цитат','Max context characters'=>'Максимальный контекст','Max hints characters'=>'Максимальное количество символов подсказок','Max input characters'=>'Максимальное количество символов входных данных','Max output tokens'=>'Максимальное количество токенов вывода','Maximum characters accepted from the input field. Default: 8 000.'=>'Максимальное количество символов, принимаемых из поля ввода. По умолчанию: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Максимальное количество символов существующего содержимого поста, передаваемого ИИ в качестве исходного контекста, если подсказки не предоставлены. По умолчанию: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Максимальное количество символов, читаемых из поля подсказок. По умолчанию: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Максимальное количество символов содержимого поста, передаваемого ИИ. 0 означает отсутствие ограничения — полное содержимое всегда отправляется (рекомендуется). Установите ненулевое значение только если у вашего провайдера есть ограничение по контексту. В журнал ошибок PHP записывается предупреждение, когда содержимое обрезается.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Максимальное число токенов, которое ИИ может сгенерировать за один ответ. Если перевод обрывается в конце, увеличьте это значение. По умолчанию: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Максимальное количество токенов, которое ИИ может сгенерировать за один запуск. Увеличьте, если статьи обрезаются полностью. По умолчанию: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Максимальное количество токенов, которое ИИ может сгенерировать за один быстрый перевод. По умолчанию: 2000.','Meta Description'=>'Мета-описание','Meta description'=>'Мета-описание','Meta Description, Excerpt Generator'=>'Генератор мета-описаний, выдержек','Meta Description, Excerpt Generator, quick translate'=>'Мета-описание, генератор аннотаций, быстрый перевод','Metric'=>'Метрика','Minimum role'=>'Минимальная роль','Missing'=>'Отсутствует','Missing pattern name or language.'=>'Отсутствует имя шаблона или язык.','Mode'=>'Режим','Model'=>'Модель','Model ID'=>'ID модели','Model tier'=>'Уровень модели','Model tiers'=>'Уровни модели','Models'=>'Модели','Modified'=>'Изменено','Most recent cached block'=>'Последний кешированный блок','Most recent cached response'=>'Последний кешированный ответ','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Многоязычная маршрутизация, полноценное многоязычное SEO (hreflang, Open Graph, Schema.org, карта сайта), и инструменты AI для контента для WordPress. Обнаружение языка, маршрутизация URL, перевод, создание контента и полноценный SEO-слой — без необходимости дополнительного плагина.','Multilingual SEO'=>'Мультиязыковое SEO','Multilingual SEO overview'=>'Обзор мультиязыкового SEO','My Account'=>'Мой аккаунт','Name'=>'Имя','Name displayed in this language. Leave empty to use the source name.'=>'Имя, отображаемое на этом языке. Оставьте пустым, чтобы использовать исходное имя.','Navigation'=>'Навигация','Navigation has no content to translate.'=>'В навигации нет содержимого для перевода.','Navigation not found.'=>'Навигация не найдена.','Navigation posts are translated via the Router tab, not this button.'=>'Посты навигации переводятся через вкладку Router, а не этой кнопкой.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Перевод навигации требует активного поставщика AI. Настройте API-ключ во вкладке API-ключи.','Navigations'=>'Навигации','Network error — could not reach the provider: %s'=>'Ошибка сети — не удалось связаться с провайдером: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'Ошибка сети — не удалось достичь конечной точки WordPress AJAX.','Network error.'=>'Ошибка сети.','Never run'=>'Никогда не запускайте','No %s version found in this translation group.'=>'В этой группе переводов не найдено версии %s.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Действие не требуется. Google устарел свой конечный пункт для пинга карты сайта в январе 2024 года и теперь обнаруживает карты сайта исключительно через директиву Sitemap в robots.txt — которая уже настроена в LF. Google обнаружит его при следующем обходе.','No active plugins detected.'=>'Обнаружены неактивные плагины.','No AI provider configured.'=>'Не настроен поставщик ИИ.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Поставщик AI не настроен. Добавьте API-ключ в Настройки → API-ключи.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Использование ИИ не зафиксировано за выбранный период (%s). Выберите более широкий диапазон выше.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Пока что не зафиксировано использование ИИ. Как только редактор выполнит перевод, сгенерирует мета-описание или использует любую другую функцию ИИ, итоги появятся здесь.','No API key configured for this provider.'=>'Для этого поставщика не настроен API-ключ.','No API key configured — enter your key in the AI Provider settings.'=>'API-ключ не настроен — введите ваш ключ в настройках провайдера AI.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Нет встроенных инструкций — каждая функция ИИ использует свои собственные настроенные параметры. Заполните поле пользовательских инструкций ниже, чтобы добавить свои правила для всего сайта.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Конфликтующие SEO-плагины не обнаружены. Lingua Forge самостоятельно управляет всеми SEO-выводами.','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Остались кредиты — пополните свой аккаунт OpenAI на platform.openai.com/account/billing.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Пока что пользовательские файлы Loco Translate не найдены. Они появятся здесь после сохранения перевода в Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Внешний OG-плагин не обнаружен. LF выводит полный набор OG + Twitter Card.','No file was selected.'=>'Файл не выбран.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Нет записей в глоссарии, соответствующих текущему фильтру. Очистите фильтр, чтобы увидеть все записи, или добавьте новую ниже.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'В глоссарии еще нет записей. Добавьте одну ниже, чтобы начать применять терминологию в переводах.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'H1 не найден. Обычно заголовок поста — это H1 — убедитесь, что ваша тема его выводит.','No images found in content.'=>'В контенте не найдено изображений.','No internal links found to update.'=>'Не найдено внутренних ссылок для обновления.','No key'=>'Нет ключа','No language-specific template parts found to map.'=>'Не найдено языко-специфичных частей шаблона для отображения.','No LF meta description set — using excerpt/content.'=>'Мета-описание LF не установлено — используется выдержка/контент.','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Правила переписывания LF не найдены. Очистите постоянные ссылки, если это неожиданно.','No links found.'=>'Ссылки не найдены.','No links found. Internal links improve crawlability and user navigation.'=>'Ссылки не найдены. Внутренние ссылки улучшают индексируемость и навигацию пользователей.','No meta description found. Generate one via the AI meta description feature.'=>'Мета-описание не найдено. Создайте его с помощью функции AI для мета-описания.','No navigation references needed updating.'=>'Нет необходимости обновлять навигационные ссылки.','No override files uploaded yet.'=>'Пока что файлы переопределения не загружены.','No PHP limit'=>'Нет лимита PHP','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Файл robots.txt физически не найден. WordPress генерирует его виртуально, и директива Sitemap LF включена автоматически.','No published posts found for the selected filters.'=>'Опубликованные посты по выбранным фильтрам не найдены.','No response from AI provider. Check your API key and try again.'=>'Нет ответа от поставщика AI. Проверьте ваш API-ключ и попробуйте снова.','No response from provider — check the error log for details.'=>'Нет ответа от провайдера — проверьте журнал ошибок для деталей.','No secondary languages configured.'=>'Настройки вторых языков не выполнены.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Конфигурация вторичных языков не выполнена. Установите языковой пакет выше, чтобы включить шаблонную структуру.','No source content found to translate.'=>'Не найдено исходного контента для перевода.','No source page linked yet.'=>'Пока что не связана исходная страница.','No template part references needed updating.'=>'Нет необходимости обновлять ссылки на части шаблона.','No terms found.'=>'Термины не найдены.','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Обнаружены сторонние SEO-плагины. Lingua Forge обрабатывает все многоязычные SEO-выводы.','No title set.'=>'Заголовок не установлен.','No translated content found. The sitemap will populate once posts have been translated.'=>'Переведенный контент не найден. Карта сайта заполнится после перевода постов.','No translation found — analyzed the source language version.'=>'Перевод не найден — проанализирована версия исходного языка.','No {lang} translation registered (TRID missing)'=>'Перевод на {lang} не зарегистрирован (TRID отсутствует)','No — WooCommerce integration class not loaded'=>'Класс интеграции WooCommerce не загружен','not a content language — see notice above'=>'не является языком контента — см. уведомление выше','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Еще не сгенерировано. Карта сайта строится при первом посещении URL карты сайта и кэшируется на 24 часа.','Notes'=>'Заметки','Nothing — all types disabled'=>'Ничего — все типы отключены','Notice message'=>'Сообщение уведомления','Notice settings'=>'Настройки уведомлений','Notify search engines'=>'Уведомить поисковые системы','Numeric permalink structure is not supported.'=>'Поддерживается структура постоянных ссылок с числовым индексом.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Теги OG/Twitter Card: обрабатываются модулем Open Graph LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Самый старый кешированный блок','Oldest cached response'=>'Самый старый кешированный ответ','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Одноразовое копирование системного отчета в виде простого текста, охватывающее все вышеуказанные разделы. Вставьте это в проблему GitHub или запрос поддержки, чтобы сразу увидеть полную среду.','Only .mo files are accepted.'=>'Допускаются только файлы .mo.','Open an issue →'=>'Открыть проблему →','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph и Twitter Cards','Open Graph output'=>'Вывод Open Graph','Open Graph settings saved.'=>'Настройки Open Graph сохранены.','Open Search Console →'=>'Открыть Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Открыть нативный диалог обмена Web Share в браузере (iOS, Android, некоторые десктопы). В случае неподдержки — копирование в буфер обмена.','OpenAI (GPT)'=>'OpenAI (GPT)','OpenAI Platform'=>'Платформа OpenAI','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Дополнительный контекст для редакторов (например, «ASIC = специализированная интегральная схема; сохранять на английском в технических контекстах»).','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Опционально. Bing уже читает директиву Sitemap: из robots.txt — это просто инициирует немедленный повторный обход, а не ждет следующего запланированного.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Опционально. Yandex уже читает директиву Sitemap: из robots.txt — это просто инициирует немедленный повторный обход, а не ждет следующего запланированного.','Order storage'=>'Хранение заказов','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Заказы в wp_posts — убедитесь, что shop_order исключен из маршрутизации LF.','Output'=>'Вывод','Output Article or WebPage schema on singular posts and pages'=>'Вывод схемы Article или WebPage для отдельных постов и страниц','Output hreflang tags in wp_head'=>'Вывод тегов hreflang в wp_head','Output mode'=>'Режим вывода','Output Open Graph tags in wp_head'=>'Вывод тегов Open Graph в wp_head','Output Product schema on WooCommerce product pages'=>'Вывод схемы Product на страницах товаров WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Вывод JSON-LD Schema.org в wp_head','Output tokens'=>'Выходные токены','Output WebSite schema on the front page and blog index'=>'Вывод схемы WebSite на главной странице и в блоге','Overall SEO score'=>'Общий рейтинг SEO','overridden'=>'переопределён','Override file deleted.'=>'Файл переопределения удален.','Override file uploaded successfully.'=>'Файл переопределения успешно загружен.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Переопределяет настройки ИИ для перевода и генерации контента на этой странице. Все остальные функции всегда используют глобальные настройки.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Переопределяет настройки ИИ для перевода и генерации контента на этой странице. Общие инструкции для сайта (Настройки → Поведение) всегда добавляются к каждому запросу независимо от этого выбора.','Overview'=>'Обзор','Page'=>'Страница','Part'=>'Часть','Paste a footnote, sentence, or any snippet here…'=>'Вставьте сноску, предложение или любой фрагмент сюда…','Paste text, or select text in the editor first…'=>'Вставьте текст или сначала выберите текст в редакторе…','Paste text, or select text on the page first…'=>'Вставьте текст или сначала выберите текст на странице…','Paste your API key…'=>'Вставьте ваш ключ API…','Path prefix (/de/)'=>'Префикс пути (/de/)','Path prefix — example.com/de/'=>'Префикс пути — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'Маршрутизация путей требует структуры постоянных ссылок на основе имени поста. Измените в','Pattern'=>'Шаблон','Pattern has no content to translate.'=>'У шаблона нет содержимого для перевода.','Pattern not found.'=>'Шаблон не найден.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Шаблон переведен и сохранен. Скопируйте содержимое в ваш пост CPT через вставщик шаблонов редактора блоков или используйте его как отправную точку для повторно используемого блока.','Pattern translation failed.'=>'Не удалось перевести шаблон.','Payment required — your account has no remaining credits.'=>'Требуется оплата — на вашем счете нет оставшихся кредитов.','Per-Post Analysis'=>'Анализ по посту','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Кэш по посту для переводов, созданных ИИ, мета-описаний, выдержек и контента. Записи автоматически аннулируются при изменении контента или провайдера/модели ИИ.','Permalink rules flushed successfully.'=>'Правила постоянных ссылок успешно очищены.','Permalink Structure'=>'Структура постоянных ссылок','Permalink structure is compatible with Lingua Forge path routing.'=>'Структура постоянных ссылок совместима с маршрутизацией путей Lingua Forge.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Навсегда удаляет все шаблоны, части шаблонов, шаблоны, меню навигации, посты, страницы, пользовательские типы постов, товары и вариации товаров, связанные с этим языком. Также удаляет файлы пакета локализации WordPress, чтобы этот язык больше не отображался в маршрутизаторе. Это действие нельзя отменить.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Навсегда удалить %s? Это удалит весь переведённый контент для этого языка и отменить нельзя.','Permission denied.'=>'Доступ запрещен.','Persuasive'=>'Убедительный','PHP constant'=>'константа PHP','PHP max_execution_time'=>'Максимальное время выполнения PHP','PHP memory_limit'=>'Ограничение памяти PHP','PHP version'=>'Версия PHP','Pin on Pinterest'=>'Закрепить на Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Закрепляйте термины, которые не должны переводиться или должны всегда отображаться определенным образом (например, названия брендов, продуктов, аббревиатуры). Ограничения глоссария внедряются в каждый запрос перевода AI для всех функций: перевод поста, метаописание, выдержка и перевод шаблонов FSE.','Ping Bing'=>'Пинг Bing','Ping Yandex'=>'Пинг Yandex','Plain language'=>'Простой язык','Plain permalinks are not supported.'=>'Простые постоянные ссылки не поддерживаются.','Please enter some instructions first…'=>'Пожалуйста, сначала введите инструкции…','Please enter some text first…'=>'Пожалуйста, сначала введите текст…','Plugin'=>'Плагин','Post'=>'Пост','Post not found or not published.'=>'Пост не найден или не опубликован.','Post not found.'=>'Пост не найден.','Post on X / Twitter'=>'Пост в X / Twitter','Post type'=>'Тип поста','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Слоги типа поста, разделенные запятыми или новыми строками. Изменения вступают в силу немедленно при сохранении — перезапуск постоянных ссылок не требуется.','Post Types'=>'Типы записей','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Посты без _lf_lang невидимы для всех фильтров языка Lingua Forge. Это может произойти при импорте контента или создании до активации плагина.','Prefilled from excerpt. Edit to override.'=>'Заполнено из аннотации. Измените для переопределения.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Цена и наличие всегда соответствуют продукту исходного языка (модель общего запаса). Теги выводятся только когда модуль Open Graph LF установлен в режим "Полный" или "Авто" без конфликтующих SEO-плагинов.','Primary content language'=>'Основной язык контента','Primary Language'=>'Основной язык','Primary language'=>'Основной язык','Primary language saved.'=>'Основной язык сохранен.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Основной язык: язык, на котором написано ваше существующее содержимое. Все переводы создаются с этого языка; его изменение не перемещает и не удаляет посты.','Processing…'=>'Обработка…','Product'=>'Товар','Product / eCommerce'=>'Продукт / Электронная коммерция','Product Open Graph'=>'Open Graph товара','Product — WooCommerce product pages'=>'Товар — страницы товаров WooCommerce','Profile'=>'Профиль','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Профили адаптируют пороги и веса к типу анализируемого контента. Профиль определяется автоматически; вы можете переопределить его для каждого анализа через выпадающее меню профиля.','Provider'=>'Провайдер','Provider error (HTTP %1$d): %2$s'=>'Ошибка провайдера (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'Провайдер не ответил. Проверьте журнал ошибок WordPress для деталей.','Provider service temporarily unavailable — try again in a moment.'=>'Сервис провайдера временно недоступен — попробуйте снова через минуту.','Quality'=>'Качество','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Качество (по умолчанию — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Качество (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'Модель качества','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Качество: используется для перевода постов и генерации контента — более высокое качество, более высокая стоимость.','Query Filter Exclusions'=>'Исключения из фильтра запросов','Quick Translate'=>'Быстрый перевод','Quick Translation'=>'Быстрый перевод','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Быстрый перевод используется в режиме фрагментов/кусочков — короткие отрывки переводятся по требованию с панели инструментов, редактора или всплывающих окон блока. Он использует отдельную, более легкую конфигурацию по сравнению с переводом всей страницы, чтобы ответы были быстрыми и экономичными.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Ограничение скорости — слишком много запросов к провайдеру; подождите немного и попробуйте снова.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Восстанавливает canLockBlocks Gutenberg. Полезно для редакционных шаблонов, которым нужно предотвратить перемещение или удаление определённых блоков.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Восстанавливает supportsTemplateMode. Основной для рабочих процессов полного редактирования сайта, где преднамеренно переопределяются шаблоны на уровне поста.','Re-generates and updates the cached result.'=>'Обновляет и обновляет кэшированный результат.','Re-scan'=>'Повторное сканирование','Re-scanning…'=>'Повторное сканирование…','Re-translate'=>'Повторный перевод','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Диагностика только для чтения для текущей установки. Здесь не изменяются настройки — используйте это для проверки конфигурации, выявления проблем и сбора информации для отчетов об ошибках.','Reading time'=>'Время чтения','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Перенаправлять посетителей на их предпочтительный язык на основе заголовка Accept-Language браузера','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Дальнейшая доработка — например, «сделать короче» или «использовать официальный тон»…','Refine further:'=>'Дополнительная доработка:','Refinement'=>'Обработка','Refinement failed — please try again.'=>'Не удалось выполнить обработку — попробуйте еще раз.','Refining…'=>'Обработка…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Восстанавливает правила переписывания WordPress, чтобы префиксы URL, языковые слаги и архивные переписывания были синхронизированы. Необходимо после изменения основного языка или добавления поддержки новых языков.','Remove stored key'=>'Удалить сохранённый ключ','Repair failed.'=>'Ремонт не удался.','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Исправьте теги каждого маршрутизируемого поста, перечисленного выше, с _lf_lang = %s. Посты в исключенных типах постов маршрутизации не трогать. Выполняйте только после импорта контента или при первоначальной активации — не используйте как инструмент массового переустановления языка.','Repair Template Metadata'=>'Исправить метаданные шаблона','Repair template metadata'=>'Исправить метаданные шаблона','Repair — assign _lf_lang = %s to all routable posts above'=>'Исправление — присвойте _lf_lang = %s всем маршрутизируемым постам выше','Repairing…'=>'Выполняется ремонт…','Report an issue on GitHub'=>'Сообщить о проблеме на GitHub','Request failed — please try again.'=>'Запрос не выполнен — попробуйте еще раз.','Request failed.'=>'Запрос не выполнен.','Request failed. Check your connection.'=>'Запрос не выполнен. Проверьте соединение.','Request failed. Please try again.'=>'Запрос не выполнен. Пожалуйста, попробуйте снова.','Requests'=>'Запросы','requests / day'=>'запросов / день','Reset'=>'Сбросить','Result will appear here…'=>'Результат появится здесь…','Retranslate'=>'Повторный перевод','Retranslating…'=>'Повторный перевод…','Review carefully — links and slugs not updated.'=>'Тщательно проверьте — ссылки и слаги не обновлены.','Review translation before applying'=>'Просмотрите перевод перед применением','Revise'=>'Пересмотреть','Revision'=>'Редакция','Revision Type'=>'Тип редакции','Rewrite Rules'=>'Правила переписывания','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt обновлён с директивой Sitemap.','Router'=>'Маршрутизатор','Router Tab'=>'Вкладка Маршрутизатор','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Выполните полный SEO-аудит всех опубликованных постов для одного или всех активных языков. Оценки сохраняются для каждого поста и отображаются в значках столбца Язык в списке постов.','Run AI Analysis'=>'Запустить анализ ИИ','Save'=>'Сохранить','Save analysis settings'=>'Сохранить настройки анализа','Save Debug Setting'=>'Сохранить настройки отладки','Save Hreflang Settings'=>'Сохранить настройки Hreflang','Save Open Graph Settings'=>'Сохранить настройки Open Graph','Save Router Settings'=>'Сохранить настройки маршрутизатора','Save Schema.org Settings'=>'Сохранить настройки Schema.org','Save Settings'=>'Сохранить настройки','Save Sitemap Settings'=>'Сохранить настройки Sitemap','Save Social Share Settings'=>'Сохранить настройки социальных кнопок','Save the post to persist changes.'=>'Сохраните пост, чтобы сохранить изменения.','Save Uninstall Setting'=>'Сохранить настройку удаления','Save WooCommerce SEO Settings'=>'Сохранить настройки SEO для WooCommerce','Saved to the meta description field when you apply.'=>'Сохраняется в поле мета-описания при применении.','Scan failed: '=>'Ошибка сканирования: ','Scan request failed. Please try again.'=>'Запрос на сканирование не удался. Пожалуйста, попробуйте снова.','Scanning posts for broken language links…'=>'Сканирование постов на наличие сломанных языковых ссылок…','Schema output deferred.'=>'Вывод схемы отложен.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD Schema.org','Schema.org output'=>'Вывод Schema.org','Schema.org settings saved.'=>'Настройки Schema.org сохранены.','Score'=>'Оценка','Score computation'=>'Вычисление оценки','Score history and badges'=>'История оценок и значки','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Оценки — это сигнал, а не вердикт. Некоторые материалы по структуре ограничены — очень короткие страницы, целевые страницы с небольшим текстом или страницы, предназначенные для навигации, могут по своей природе иметь более низкую оценку. Используйте этот обзор для выявления реальных разрывов в паритете между языками, а не для гонки за числом.','Search'=>'Поиск','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Консоль поиска полезна для мониторинга ошибок индексирования и покрытия, но не обязательна для обнаружения.','Search Results'=>'Результаты поиска','Sections'=>'Разделы','Security check failed — file path is not permitted.'=>'Ошибка проверки безопасности — путь к файлу не разрешен.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Посмотрите в Настройки → SEO → Совместимость для полной таблицы поведения по функциям.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Выберите язык для управления его шаблонами FSE, частями шаблонов и меню навигации.','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Выберите пост и выполните подробный SEO-аудит, чтобы увидеть результаты по метрикам и оценку для конкретного элемента.','Select language'=>'Выберите язык','Send via Telegram'=>'Отправить через Telegram','Send via WhatsApp'=>'Отправить через WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Анализ SEO','SEO character-count info'=>'Информация о количестве символов для SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Обнаружены плагины SEO: %s. LF выводит только og:locale и og:locale:alternate; обнаруженный плагин обрабатывает полный набор OG.','SEO Plugins'=>'SEO-плагины','SEO plugins and conflict avoidance:'=>'Плагины SEO и предотвращение конфликтов:','SEO Score System'=>'Система оценки SEO','SEO Scores'=>'Оценки SEO','SEO Tab'=>'Вкладка SEO','Server setup (subdomain)'=>'Настройка сервера (поддомен)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Устанавливает поведение ИИ по умолчанию для всех функций на сайте. Отдельные посты могут переопределять это для перевода и генерации контента через метабокс Lingua Forge.','Settings'=>'Настройки','Settings saved.'=>'Настройки сохранены.','Settings → General → Site Language'=>'Настройки → Общие → Язык сайта','Settings → Permalinks'=>'Настройки → Постоянные ссылки','Share on Facebook'=>'Поделиться на Facebook','Share on LinkedIn'=>'Поделиться на LinkedIn','Share on Mastodon'=>'Поделиться на Mastodon','Share via email (mailto:)'=>'Поделиться по электронной почте (mailto:)','Shared / compatibility mode'=>'Режим совместного использования / совместимости','Shop'=>'Магазин','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Краткий контент (не более 3 параграфов) никогда не штрафуется за отсутствие подзаголовков, независимо от профиля. Краткая страница не выигрывает от принудительной структуры заголовков.','Show home link'=>'Показать ссылку на главную','Shown when no translation exists for the visitor\'s language.'=>'Показано, когда для языка посетителя не существует перевода.','Single'=>'Одиночная','Single %s'=>'Единичный %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Заголовок из одного слова (%d символов) — добавление второго слова повышает ясность и охват ключевых слов.','Single: %s'=>'Единичный: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Общий лимит запросов к ИИ на сайте за сутки по UTC (учитывает как переводы в панели инструментов, так и ревизии блоков). Счетчик сбрасывается в полночь по UTC. Установите 0 для отключения ограничения.','Sitemap'=>'Карта сайта','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Кэш карты сайта очищен. Он будет воссоздан при следующем посещении URL карты сайта.','Sitemap output'=>'Вывод карты сайта','Sitemap settings saved.'=>'Настройки карты сайта сохранены.','Sitemap URL'=>'URL карты сайта','Size'=>'Размер','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Блок социальных иконок: URL-адреса: обрабатываются встроенным модулем LF Social Share (SEO → Social Share)','Social Share'=>'Общий доступ','Social Share settings saved.'=>'Настройки общего доступа в соцсетях сохранены.','Some link fixes failed.'=>'Некоторые исправления ссылок не удались.','Some nav ref fixes failed.'=>'Некоторые исправления навигационных ссылок не удались.','Some part fixes failed.'=>'Некоторые исправления частей не удались.','Some parts could not be created.'=>'Некоторые части не удалось создать.','Some templates could not be created.'=>'Некоторые шаблоны не удалось создать.','Some translations failed.'=>'Некоторые переводы не удались.','source'=>'источник','Source file not found.'=>'Исходный файл не найден.','Source lang'=>'Исходный язык','Source language'=>'Исходный язык','Source term'=>'Исходный термин','Source title'=>'Исходный заголовок','Standard'=>'Стандартный','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Стандарт использует собственную настроенную температуру каждой функции: перевод T=0.2 (точный), быстрый перевод T=0.4, генерация контента T=0.6 (креативный). Другие предустановки применяют одну фиксированную температуру ко всем функциям.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Начинайте вводить в любое поле, чтобы увидеть предложения модели, или используйте таблицу ссылок ниже. Модели качества Light и mid-tier (Haiku, GPT-4o mini, Gemini Flash) полностью подходят для перевода и генерации контента — флагманские модели "max" увеличивают стоимость с минимальным приростом качества для структурированного текста.','Status'=>'Статус','Status / Actions'=>'Статус / Действия','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Хранит необработанные ответы AI, связанные по хешу содержимого, паре языков, поставщику, модели и предустановке. Записи кэша автоматически аннулируются при изменении исходного содержимого поста. Очистите отдельные записи постов или весь кэш на этой вкладке.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Хранит полный перевод поста по хешу содержимого. Включено по желанию (включено в Поведение). Ускоряет повторные переводы неизмененного содержимого. Очистите его здесь, чтобы принудительно выполнить новый проход AI независимо от изменений содержимого.','Storytelling'=>'Рассказывание историй','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Режим строгого сохранения для юридического, нормативного, медицинского или технического контента. Включённый режим использует низкую температуру выборки для всех функций ИИ и добавляет нижеуказанный дополнение к системной подсказке — терминология, номера статей, единицы измерения, торговые марки и нормативный язык сохраняются дословно, а не перефразируются.','Structured Outline'=>'Структурированный план','Subdomain (de.example.com)'=>'Поддомен (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Режим поддомена требует, чтобы ваш веб-сервер указывал все языковые поддомены (например, de.example.com) на эту установку WordPress. После переключения режимов обновите правила постоянных ссылок и очистите кеши. Если ваш домашний URL включает www (например, www.example.com), используйте фильтр lf_base_domain для установки базового домена, чтобы поддомены создавались правильно.','Subdomain — de.example.com/'=>'Поддомен — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Отправьте этот URL в Google Search Console вместе с вашей основной картой сайта.','Submit to Reddit'=>'Отправить на Reddit','Suggested meta description'=>'Рекомендуемое мета-описание','Suggested title'=>'Рекомендуемый заголовок','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Поддерживаемые поставщики: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Выберите активного поставщика из выпадающего списка — используется только один поставщик одновременно. Введите API-ключ для этого поставщика, чтобы включить функции AI.','Suppressed: %s.'=>'Подавлено: %s.','Switch to a post-name based structure in'=>'Переключиться на структуру на основе имени поста в','System'=>'Система','System Tab'=>'Вкладка системы','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, для каждой функции','Tag'=>'Тег','Tags emitted'=>'Выводимые теги','Target lang'=>'Целевой язык','Target Language'=>'Целевой язык','Target language'=>'Целевой язык','Target term'=>'Целевой термин','Target: 140–160 chars for optimal SERP display'=>'Цель: 140–160 символов для оптимального отображения в SERP','Technical'=>'Технический','Technical / Scientific'=>'Технический / Научный','Technical / Scientific instructions'=>'Технические / научные инструкции','Template "%s" already exists.'=>'Шаблон "%s" уже существует.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Шаблон "{expected}" не существует — сначала создайте его в редакторе сайта.','Template has no content.'=>'У шаблона нет содержимого.','Template mode'=>'Режим шаблона','Template not found or not stored in the database.'=>'Шаблон не найден или не сохранен в базе данных.','Template part "%s" already exists.'=>'Часть шаблона "%s" уже существует.','Template part has no content.'=>'У части шаблона нет содержимого.','Template part not found or not stored in the database.'=>'Часть шаблона не найдена или не сохранена в базе данных.','Template Parts'=>'Части шаблонов','Templates'=>'Шаблоны','Test connection'=>'Проверить соединение','Testing…'=>'Идет тестирование…','Text domain / locale'=>'Текстовая область / локаль','Text to translate'=>'Текст для перевода','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Кэш ответов API хранит необработанный результат каждого запроса ИИ — перевод, мета-описание, выдержка и генерация контента — по хэшу входных данных (контент, пара языков, провайдер, модель). Отключите при настройке подсказок или когда требуется, чтобы каждый запрос достигал провайдера ИИ. Отключение не удаляет кэшированные записи — повторное включение восстанавливает их.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Дневная норма (настроена в Поведение → Ограничения) отслеживается здесь. Когда норма достигнута, вызовы AI приостанавливаются на остальную часть дня. Таблица показывает, сколько из нормы использовано.','The editor did not accept the content — please try again.'=>'Редактор не принял содержимое — попробуйте еще раз.','The following directive is active in your virtual robots.txt:'=>'Следующая директива активна в вашем виртуальном файле robots.txt:','The lf-social-share mu-plugin is active.'=>'Плагин lf-social-share активен.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Плагин lf-social-share активен. Встроенная функция Social Share Lingua Forge неактивна — плагин управляет переписыванием URL для обмена и действиями JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Уровень Light использует быструю модель, настроенную в таблице моделей выше (по умолчанию: Haiku / Flash). Переключитесь на качество, если вам нужна такая же точность перевода, как в режиме полной страницы для фрагментов.','The phrase as it appears in the source text.'=>'Фраза, как она указана в исходном тексте.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Основной язык всегда обслуживается в корне вашего сайта — без префикса URL в режиме пути, без субдомена языка в режиме субдомена. Все остальные языки используют либо префикс пути /lang/ (например, example.com/de/), либо субдомен языка (например, de.example.com), в зависимости от настройки структуры URL ниже.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Вкладка SEO → Совместимость показывает статус обнаружения в реальном времени и точно объясняет, что делает LF для каждой области функций.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL для обмена всегда отражает текущую страницу — ручной ввод URL не требуется. Фильтр linguaforge_social_share_url позволяет переопределить разрешённый URL для любой службы.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Карта сайта автоматически объявляется в robots.txt. Все основные поисковые системы — Google, Bing, Яндекс — обнаруживают её из robots.txt. Ручная отправка не требуется.','The source page has no footnotes.'=>'На исходной странице нет сносок.','The upload failed — please try again.'=>'Загрузка не удалась — попробуйте еще раз.','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Таблица использования показывает расход токенов AI по функциям (перевод, мета-описание, выдержка, шаблон FSE, пакетный анализ), поставщику и модели. Используйте кнопки диапазона дат для фильтрации по сегодня, последние 7 дней, последние 30 дней или все время.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Карта сайта WordPress перечисляет все URL вашего контента. Карта сайта LF сообщает поисковым системам, как связаны языковые версии через альтернативы xhtml:link hreflang. Отправьте обе в Google Search Console для полного охвата.','The WordPress site language (%1$s) is not among the active Lingua Forge content languages (%2$s). This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'Язык сайта WordPress (%1$s) не входит в список активных языков контента Lingua Forge (%2$s). Это вызывает нулевые результаты при запросах товаров WooCommerce, сбои изображений товаров и нарушение всех запросов с фильтрацией по языкам.','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Язык сайта WordPress (Настройки → Общие → Язык сайта) должен быть установлен на один из языков, которые вы используете для контента — либо основной язык контента, либо один из вторичных языков. Он не может быть языком, для которого на сайте нет контента.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Эти сноски взяты с исходной страницы и показаны здесь только для справки. Добавьте их на эту страницу с помощью редактора блоков.','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Этот каталог обновляется с каждым выпуском Lingua Forge. Тестирование соединения во вкладке API Keys также получает список живых моделей от провайдера и обновляет вышеуказанные предложения.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Это системная страница WooCommerce (Магазин, Корзина, Оформление заказа и т. д.). Ее содержимое управляется WooCommerce — оценка отражает только структурные сигналы, а не редактируемый пользователем SEO-контент.','This is the source page. Footnotes are edited directly in the block editor.'=>'Это исходная страница. Сноски редактируются прямо в редакторе блоков.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Этот ключ в настоящее время предоставляется сервером %s и не может быть удалён здесь. Введите новый ключ выше, чтобы переопределить его значением из базы данных.','This language is protected and cannot be uninstalled.'=>'Этот язык защищён и не может быть удалён.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Этот язык соответствует локали WordPress и не может быть удалён.','Tier'=>'Уровень','Tip: to reset a model to the built-in default, clear the field and save.'=>'Совет: чтобы сбросить модель к встроенному значению по умолчанию, очистите поле и сохраните.','Title'=>'Заголовок','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Заголовок 15 баллов · Мета-описание 20 баллов · Количество слов 15 баллов · Заголовки 20 баллов · Изображения 10 баллов · Ссылки 10 баллов. Ограничение заголовка в SERP 60 символов; мета-описания 120–210 символов; предупреждение при менее 300 слов, ошибка при менее 100; требуется H2; внутренние ссылки обязательны.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Заголовок содержит %1$d символов — может быть обрезан в результатах поиска (старайтесь не превышать %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Заголовок содержит только %d символов — старайтесь использовать минимум 10 символов.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Правила оценки заголовка (все профили): неудача, если пустой; предупреждение, если менее 10 символов; предупреждение, если только одно слово; предупреждение, если длиннее лимита SERP профиля (60 символов для блога, 70 для продукта/посадки); OK, если не менее 10 символов, не менее 2 слов и в пределах лимита SERP.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Чтобы использовать пользовательский секрет шифрования (вместо полученного значения wp_salt), добавьте это в wp-config.php:','Today'=>'Сегодня','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Потребление токенов суммировано по функциям, поставщикам и моделям. Записывается при каждом успешном вызове ИИ; тестовые пинги исключены, чтобы не искажать итоги.','Token usage'=>'Использование токенов','Tone'=>'Тон','tone'=>'тон','Tone:'=>'Тон:','Too many AI requests. Please retry in %d seconds.'=>'Слишком много запросов к ИИ. Пожалуйста, повторите через %d секунд.','Total'=>'Итого','Total tokens'=>'Общее количество токенов','Translate'=>'Перевести','Translate / Revise'=>'Перевести / Пересмотреть','Translate / Revise block'=>'Перевести / Пересмотреть блок','Translate all'=>'Перевести всё','Translate all %s terms (AI)'=>'Перевести все термины %s (ИИ)','Translate all categories (AI)'=>'Перевести все категории (ИИ)','Translate all labels (AI)'=>'Перевести все метки (ИИ)','Translate all tags (AI)'=>'Перевести все теги (AI)','Translate all terms (AI)'=>'Перевести все термины (AI)','Translate chunk'=>'Перевести фрагмент','Translate Content'=>'Перевести контент','Translate missing'=>'Перевод отсутствует','Translate page…'=>'Перевод страницы…','Translated content'=>'Переведённое содержание','Translated Labels'=>'Переведённые метки','Translated Names'=>'Переведённые имена','Translated title'=>'Переведённый заголовок','Translated to:'=>'Переведено на:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Переведено. Проверьте в редакторе сайта — внутренние ссылки, URL-адреса навигации и слаги шаблонов не обновляются автоматически.','Translating…'=>'Перевод…','Translation Caching'=>'Кэширование переводов','Translation caching'=>'Кэширование переводов','Translation failed. Check the browser console.'=>'Не удалось выполнить перевод. Проверьте консоль браузера.','Translation found but permalink could not be generated'=>'Обнаружен перевод, но постоянная ссылка не может быть сгенерирована','Translation Limits'=>'Ограничения перевода','Translation Limits & Behavior'=>'Ограничения и поведение при переводе','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Ограничения на перевод: управлять ролями пользователей, которые могут запускать перевод AI, и установить месячный бюджет токенов. Превышение бюджета приостанавливает вызовы AI до следующего месяца.','Translation Memory'=>'Память переводов','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Кэш памяти переводов сохраняет результаты AI по хэшу содержимого, паре языков, поставщику и модели. Редактирование поста аннулирует запись кэша, чтобы следующий вызов перевода получил свежий результат.','Translation Memory cleared. %d cached block was removed.'=>'Кеш памяти перевода очищен. Удален %d закешированный блок.' . "\0" . 'Кеш памяти перевода очищен. Удалено %d закешированных блоков.' . "\0" . '','Translation Memory setting saved.'=>'Настройка памяти переводов сохранена.','Translation workflow'=>'Рабочий процесс перевода','Translation, Content Generator'=>'Перевод, генератор контента','Treat H2 as H1 equivalent'=>'Обрабатывать H2 как эквивалент H1','Type'=>'Тип','Uli Hake'=>'Ули Хаке','Unexpected provider error (HTTP %d).'=>'Неожиданная ошибка провайдера (HTTP %d).','Uninstall %s'=>'Удалить %s','Uninstall Behaviour'=>'Удаление поведения','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Поведение при удалении: контролирует, что удаляется при удалении плагина через Plugins → Installed Plugins → Delete. Настройки плагина и кэши AI всегда удаляются. Назначения языков, связи переводов, метаописания, глоссарий и Память переводов по умолчанию сохраняются, чтобы случайное удаление или повторная установка могли продолжить работу. Включите "Удалять данные контента при удалении" только тогда, когда вы полностью удаляете мультиязычную поддержку с сайта — это нельзя отменить.','Uninstall setting saved.'=>'Настройка удаления сохранена.','unknown error'=>'неизвестная ошибка','Unknown provider.'=>'Неизвестный поставщик.','Unknown search engine.'=>'Неизвестная поисковая система.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'В отличие от hreflang — где LF всегда переопределяет другие плагины, потому что они не знают вашей мультиязычной конфигурации — Open Graph отличается: плагины Yoast, Rank Math и подобные уже выводят правильные OG-теги для вашего контента. Их дублирование не добавляет ценности. В автоматическом режиме LF обнаруживает активные SEO-плагины и добавляет только то, что они не могут обеспечить: og:locale (текущий язык) и og:locale:alternate (все другие настроенные языки).','Unlimited'=>'Неограниченно','Up'=>'Вверх','Upload .mo file'=>'Загрузить файл .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Загружайте скомпилированные файлы .mo, чтобы переопределить строки сторонних плагинов для конкретных локалей — например, пользовательский перевод VikBooking, использующий "apartment" вместо "room". Файлы должны соответствовать соглашению о наименовании WordPress: {textdomain}-{locale}.mo (например, vikbooking-ca.mo). Они хранятся в папке uploads и сохраняются при обновлении плагина.','Upload Override'=>'Загрузить переопределение','URL could not be mapped to a post — check the link target exists'=>'URL не удалось сопоставить с постом — проверьте, существует ли целевой объект','URL structure'=>'Структура URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Структура URL: режим с префиксом пути (example.com/de/) не требует изменений на сервере. Режим с поддоменом (de.example.com) требует записи DNS с подстановочным знаком, сертификата SSL с подстановочным знаком и изменения конфигурации веб-сервера — см. руководство по настройке сервера.','URL to enter'=>'URL для ввода','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Используйте нативный обмен, когда он доступен; в противном случае — копирование в буфер обмена. Рекомендуемый по умолчанию для кнопок "Поделиться".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Используйте вкладки в верхней части этой страницы для настройки каждого раздела. Изменения во вкладке маршрутизатора вступают в силу немедленно; изменения ключей AI и настроек модели применяются к следующему запросу AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Таблица терминов, управляемая пользователем, для каждой языковой пары. Записи добавляются в подсказку системы перевода, чтобы ИИ использовал предпочтительные термины последовательно — критично для терминологии области («кВт», «PPA», «точка подключения»), названий брендов, которые не должны переводиться, и стандартизированной нормативной формулировки. Обе языковые поля являются необязательными: оставьте «Исходный язык» пустым, чтобы применить запись независимо от языка исходного текста; оставьте «Целевой язык» пустым, чтобы применить её ко всем целевым языкам сразу.','Using custom meta description.'=>'Использование пользовательского мета-описания.','Using LF AI meta description.'=>'Использование мета-описания LF AI.','Value source'=>'Источник значения','Version'=>'Версия','View'=>'Просмотр','View built-in default'=>'Просмотр встроенного значения по умолчанию','View current robots.txt'=>'Просмотр текущего файла robots.txt','View details'=>'Просмотреть детали','View Lingua Forge details'=>'Просмотреть детали Lingua Forge','Visit plugin site'=>'Посетить сайт плагина','Warning:'=>'Внимание:','WcPageBridge active'=>'Активирован WcPageBridge','WebSite'=>'Веб-сайт','WebSite — front page / blog index'=>'Веб-сайт — главная страница / блог','What LF provides — and collision avoidance'=>'Что предоставляет LF — и избегание конфликтов','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Что предоставляет LF: теги hreflang для каждого настроенного языка, теги Open Graph и Twitter Card с og:locale и og:locale:alternate, Schema.org JSON-LD с аннотациями inLanguage и отдельная мультиязычная карта сайта по адресу /lf-sitemap.xml с альтернативными записями xhtml:link для всех групп переводов.','When another SEO plugin is installed'=>'Когда установлен другой SEO-плагин','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Когда включено ведение журнала отладки (через переключатель ниже или определяя LINGUAFORGE_AI_DEBUG в wp-config.php), функции перевода и шаблонов FSE записывают свои необработанные подсказки AI и ответы на диск для устранения неполадок. Используйте этот раздел для мониторинга этого вывода и очистки его после получения нужных данных — файлы могут быстро расти на больших страницах. Настройте каталог назначения через фильтр linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'При включении, посетители в первый раз без cookie языка и без префикса языка в URL перенаправляются на наиболее подходящую версию языка. Перенаправление пропускается, если предпочтительный язык браузера не входит в активные языки маршрутизатора. После выбора языка через переключатель, приоритет имеет cookie, и заголовок браузера игнорируется при всех последующих посещениях.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'При включении LF выводит дополнительные метатеги на страницах товаров: og:type=product, og:price:amount, og:price:currency, og:availability и их аналоги из пространства product, используемые Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'При включении URL карты сайта автоматически объявляется в robots.txt, и кэш обновляется при сохранении переведённого контента.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Когда профиль блога требует H2, и его нет, анализатор сначала проверяет наличие подзаголовков H3, прежде чем выдавать предупреждение. Аккордеоны и блоки Details по умолчанию используют H3 для заголовков; эти H3 считаются допустимой структурой и дают результат OK, а не предупреждение.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Когда язык сайта WP не является языком контента: запросы товаров WooCommerce возвращают нулевые результаты во всех блоках каталога; делегирование изображений товаров не работает; все запросы контента с фильтрацией по языкам ломаются; переключатель языков может показывать ложную опцию не контентного языка. Если в верхней части вкладки Router или System появляется красное предупреждение о конфигурации, сначала исправьте язык сайта.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Когда активированы Yoast SEO, Rank Math, All in One SEO или SEOPress, Lingua Forge автоматически подавляет их вывод hreflang через фильтр. Общие SEO-плагины создают hreflang на основе однолинейной структуры URL и не учитывают вашу мультиязычную маршрутизацию; вывод LF всегда корректен.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Какой уровень модели использовать для перевода всей страницы. Качество использует модель, настроенную в таблице моделей выше, и рекомендуется для точного, длинного перевода. Переключайтесь на Легкий только если важна скорость или стоимость, а содержание короткое.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Пока активен, плагин управляет базовым набором OG, и LF выводит только теги локали (автоматический режим). Удаление его автоматически переводит LF в полный режим OG.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce не активен.','WooCommerce page translations'=>'Переводы страниц WooCommerce','WooCommerce product price'=>'Цена товара WooCommerce','WooCommerce SEO settings saved.'=>'Настройки SEO WooCommerce сохранены.','WooCommerce store currency'=>'Валюта магазина WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Страницы системы WooCommerce (Магазин, Корзина, Оформление заказа, Мой аккаунт) исключены — их содержимое управляется WooCommerce и не может быть улучшено через SEO-редакции.','WooCommerce version'=>'Версия WooCommerce','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Версия WooCommerce, режим хранения заказов (CPT / HPOS / общий) и таблица охвата переводов по языкам для четырёх встроенных страниц WC (Магазин, Корзина, Оформление заказа, Мой аккаунт).','Word count'=>'Количество слов','WordPress version'=>'Версия WordPress','WP core canonical active (hreflang disabled)'=>'Ядро WP активировано (hreflang отключён)','WP instance language'=>'Язык экземпляра WP','WP site language requirement'=>'Требование к языку сайта WP','WP-CLI reference'=>'Справка WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Записывать подсказки AI и ответы на диск для устранения неполадок','XML Sitemap'=>'XML-карта сайта','Yes'=>'Да','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Вы также можете определить ключи как константы или переменные окружения (например, в wp-config.php). Эти источники используются автоматически в качестве резервного варианта, когда ключ из базы данных не сохранён.','You do not have permission to manage these settings.'=>'У вас нет разрешения управлять этими настройками.','You do not have permission to read this post.'=>'У вас нет разрешения на чтение этого поста.','{n} stale path(s)'=>'{n} устаревший(ие) путь(и)','~%d min read'=>'~%d мин чтения' . "\0" . '~%d мин чтения' . "\0" . '','— AI features are disabled.'=>'— Функции AI отключены.','— Any source language —'=>'— Любой исходный язык —','— Any target language —'=>'— Любой целевой язык —','— Any target —'=>'— Любой целевой —','— Any —'=>'— Любой —','— Auto-detect —'=>'— Автоматический выбор —','— auto-detect —'=>'— автоопределение —','— Deferred to plugin'=>'— Передано плагину','— Disabled'=>'— Отключено','— Not detected'=>'— Не обнаружено','— select a language —'=>'— выберите язык —','← Back'=>'← Назад','↑ Detected from current post'=>'↑ Обнаружено из текущего поста','→ Locale tags only (manual setting)'=>'→ Только теги локали (ручная настройка)','→ Locale tags only — deferring base OG to plugin'=>'→ Только теги локали — откладываем базовый OG на плагин','↺ Re-translate'=>'↺ Повторный перевод','↺ Refine'=>'↺ Доработка','↺ Refresh'=>'↺ Обновить','↺ Refresh AI Analysis'=>'↺ Обновить AI-анализ','↺ Refreshing…'=>'↺ Обновление…','⚠ Borderline'=>'⚠ Граничное значение','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Не найдены посты <strong>{lang}</strong>. Убедитесь, что все переведённые посты имеют мета-параметр Язык, установленный в <strong>{lang}</strong> в метаблоке языка.','⚠ No changes'=>'⚠ Нет изменений','⚠ No changes — re-scan?'=>'⚠ Нет изменений — повторное сканирование?','✅ Fixed ({n})'=>'✅ Исправлено ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Не обнаружено сломанных ссылок или несоответствий шаблонов для <strong>{lang}</strong>. Проведено сканирование <strong>{scanned}</strong> постов и страниц — все проверки прошли успешно. Ссылки на части шаблонов (шапка, подвал, боковая панель) здесь не включены — используйте кнопку Исправить части шаблонов для их отдельной проверки.','✅ Template fixed'=>'✅ Шаблон исправлен','✓ %s notified successfully.'=>'✓ %s успешно уведомлено.','✓ Active'=>'✓ Активно','✓ Active at /lf-sitemap.xml'=>'✓ Активно в /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Активно — %d записи URL с языковыми альтернативами' . "\0" . '✓ Активно — %d записей URL с языковыми альтернативами' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ Активно — полный OG + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Активно — только теги локали (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Все части созданы.','✓ All templates created.'=>'✓ Все шаблоны созданы.','✓ All translated.'=>'✓ Все переведено.','✓ Configured'=>'✓ Настроено','✓ Connection OK'=>'✓ Соединение в порядке','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Контент сгенерирован — посмотрите оверлей для просмотра, доработки и применения.','✓ Done'=>'✓ Готово','✓ Enabled'=>'✓ Включено','✓ Good length'=>'✓ Хорошая длина','✓ Hreflang active'=>'✓ Hreflang активен','✓ In safe storage'=>'✓ В безопасном хранилище','✓ Language installed.'=>'✓ Язык установлен.','✓ LF outputs'=>'✓ Выводы LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Выводы LF Article / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Выводы LF — полный OG + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ Выводы LF — плагин hreflang отключен','✓ Links fixed.'=>'✓ Ссылки исправлены.','✓ Nav refs fixed.'=>'✓ Исправлены навигационные ссылки.','✓ Parts fixed.'=>'✓ Части исправлены.','✓ Pattern translated.'=>'✓ Шаблон переведен.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Обнаружен физический robots.txt. В директиве Sitemap LF он присутствует.','✓ Refined — review the updated draft above.'=>'✓ Обработано — просмотрите обновленный черновик выше.','✓ Translation saved'=>'✓ Перевод сохранён','✓ WP core canonical removed'=>'✓ Удален канонический URL ядра WP','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ Не удалось выполнить пинг %s. URL карты сайта все еще объявляется в robots.txt — поисковая система обнаружит его при следующем обходе.','✗ Disabled'=>'✗ Отключено','✗ Error:'=>'✗ Ошибка:','✗ Failed:'=>'✗ Не удалось: ','✗ Not configured'=>'✗ Не настроено','✗ Too long'=>'✗ Слишком длинно','✗ Too short'=>'✗ Слишком коротко','❌ Failed'=>'❌ Не удалось','📄 Wrong template'=>'📄 Неправильный шаблон','📍 Stale path (page moved)'=>'📍 Устаревший путь (страница перемещена)']];
